class Inventory:
    def __init__(self, capacity=10):
        self.items = []
        self.capacity = capacity

    def add(self, item):
        if len(self.items) < self.capacity:
            self.items.append(item)
            return True
        return False

    def remove(self, item):
        if item in self.items:
            self.items.remove(item)
            return True
        return False

    def display(self):
        if not self.items:
            return "Empty"
        return "\n".join(f"- {item}" for item in self.items)

    def count(self):
        return len(self.items)

class Potion:
    def __init__(self, name, effect, value):
        self.name = name
        self.effect = effect
        self.value = value

    def use(self, target):
        print(f"Used {self.name} on {target}: {self.effect}")

# Create inventory
inventory = Inventory()

# Add items
inventory.add("Health Potion")
inventory.add("Mana Potion")
inventory.add("Antidote")

print(f"Inventory ({inventory.count()}/{inventory.capacity}):")
print(inventory.display())

# Remove item
inventory.remove("Mana Potion")

print(f"\nInventory ({inventory.count()}/{inventory.capacity}):")
print(inventory.display())
